function countUniqueShipped(events) {
  // events: array of { orderId, type, at }
  // TODO: return the number of unique OrderShipped events, where a
  // duplicate shares the exact same orderId, type, and at (a redelivery).
  return events.length;
}

items.solution:
function countUniqueShipped(events) {
  const seen = new Set();
  let count = 0;
  for (const e of events) {
    if (e.type !== 'OrderShipped') continue;
    const key = `${e.orderId}:${e.type}:${e.at}`;
    if (seen.has(key)) continue;
    seen.add(key);
    count++;
  }
  return count;
}

