  // attemptResults: array of booleans, true = that attempt succeeded
  // TODO: return "delivered" if any attempt within the first
  // maxDeliveries attempts succeeds, otherwise "dead-lettered".
  return "";
}

items.solution:
function deliveryOutcome(attemptResults, maxDeliveries) {
  for (let i = 0; i < Math.min(attemptResults.length, maxDeliveries); i++) {
    if (attemptResults[i]) return 'delivered';
  }
  return 'dead-lettered';
}

