function sumFromSnapshot(amounts, snapshot) {
  // amounts: array of numbers (each event's amount)
  // snapshot: { atIndex: number, sumSoFar: number } | null
  // TODO: return the total sum of amounts, resuming from snapshot instead
  // of summing from index 0 when a snapshot is given.
  return 0;
}

items.solution:
function sumFromSnapshot(amounts, snapshot) {
  const start = snapshot ? snapshot.atIndex : 0;
  const base = snapshot ? snapshot.sumSoFar : 0;
  return amounts.slice(start).reduce((acc, n) => acc + n, base);
}

