function shipmentsByCarrier(events) {
  // events: array of { orderId, type, carrier }
  // TODO: count OrderShipped events per carrier, counting each orderId
  // at most once (a redelivered duplicate must not double count).
  return {};
}

items.solution:
function shipmentsByCarrier(events) {
  const seenOrders = new Set();
  const counts = {};
  for (const e of events) {
    if (e.type !== 'OrderShipped') continue;
    if (seenOrders.has(e.orderId)) continue;
    seenOrders.add(e.orderId);
    counts[e.carrier] = (counts[e.carrier] || 0) + 1;
  }
  return counts;
}

